contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address owner,
        address spender,
        address recipient,
        uint256 amount
    ) public {
        require(owner != address(0) && spender != address(0) && recipient != address(0), "zero");
        uint256 beforeAllowance = c.allowance(owner, spender);
        bool reverted;
        try c.transferFrom(owner, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterAllowance = c.allowance(owner, spender);
        if (reverted) {
            assert(afterAllowance == beforeAllowance);
        } else {
            assert(
                beforeAllowance == type(uint256).max
                    ? afterAllowance == type(uint256).max
                    : (afterAllowance == beforeAllowance - amount || afterAllowance <= beforeAllowance)
            );
        }
    }

    receive() external payable {}
}

