contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 transferAmount, uint256 burnAmount, uint256 mintAmount) public {
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 transferAmountCapped = balBefore == 0 ? 0 : (transferAmount % (balBefore + 1));
        bool transferOk;
        try c.transfer(address(0xdead), transferAmountCapped) { transferOk = true; } catch { transferOk = false; }
        uint256 supplyAfterTransfer = c.totalSupply();

        uint256 supplyBeforeBurn = c.totalSupply();
        uint256 burnCapped = burnAmount % (supplyBeforeBurn + 1);
        uint256 balBeforeBurn = c.balanceOf(address(this));
        bool burnOracle = balBeforeBurn >= burnCapped;
        bool burnOk;
        try c.burn(burnCapped) { burnOk = true; } catch { burnOk = false; }
        uint256 supplyAfterBurn = c.totalSupply();

        bool mintOk;
        try c.mintSynth(address(this), mintAmount) { mintOk = true; } catch { mintOk = false; }
        uint256 supplyAfterMint = c.totalSupply();

        assert(
            supplyAfterTransfer == supplyBefore &&
            (burnOracle ? (burnOk && supplyAfterBurn == supplyBeforeBurn - burnCapped) : (!burnOk && supplyAfterBurn == supplyBeforeBurn)) &&
            (!mintOk && supplyAfterMint == supplyAfterBurn)
        );
    }
}

