contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "recipient must be nonzero");
        require(recipient != address(this), "recipient must differ from caller");
        require(amount > 0, "amount must be positive");

        c.mintSynth(address(this), amount);

        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(recipient);
        require(beforeSender >= amount, "caller must have enough balance");

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.balanceOf(address(this)) == beforeSender - amount && c.balanceOf(recipient) == beforeRecipient + amount);
    }

    receive() external payable {}
}

