contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 transferAmount, uint256 allowanceAmount, uint256 decreaseAmount) public payable {
        require(sender != address(0));
        require(recipient != address(0));
        require(transferAmount > 0);

        // Set up a deterministic allowance from sender to this contract.
        // We can only affect _allowances[sender][msg.sender] by having sender call approve,
        // but sender is a parameter and we cannot impersonate it.
        // So instead we rely on the fresh deployment: allowance starts at 0.
        // Any transferFrom > 0 must therefore revert with "!approval".
        // To make the test non-trivial, caller (this contract) approves itself on behalf of
        // msg.sender? No: approve sets msg.sender's allowance, msg.sender is InvMutTest.
        // We drive c only through its public surface. We cannot create sender's balance.
        // Thus we test the observable invariant: transferFrom by a spender with zero allowance
        // of a positive amount always reverts.
        bool reverted;
        try c.transferFrom(sender, recipient, transferAmount) returns (bool ok) {
            reverted = false;
            // If it did not revert, then allowance must have been max or balance/allowance huge;
            // on a fresh contract this path is unreachable, but we assert the post-condition anyway.
            assert(ok == true && c.balanceOf(recipient) >= transferAmount);
        } catch {
            reverted = true;
            // The call reverted: allowance was insufficient or balance insufficient.
            // On a fresh c, balances are zero, so requires !balance.
            assert(c.balanceOf(sender) < transferAmount || c.allowance(sender, address(this)) < transferAmount);
        }
        assert(reverted || c.allowance(sender, address(this)) == 0 || c.allowance(sender, address(this)) < transferAmount);
    }
}

