contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address pool,
        address user,
        uint lpToAdd,
        uint synthAmount,
        uint otherSynthAmount
    ) public payable {
        // --- setup: give this test contract some LP tokens and approve c to pull them ---
        require(lpToAdd > 0 && lpToAdd < 2**255);
        require(synthAmount > 0);

        // Try to make c the holder of LP tokens by transferring LP tokens to c.
        bool gotLp;
        try iBEP20(pool).transfer(address(c), lpToAdd) { gotLp = true; } catch { gotLp = false; }

        uint beforeLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforeLPDebt = c.getmapAddress_LPDebt(pool);
        uint beforeSupply = c.totalSupply();
        uint cLpBalance = iBEP20(pool).balanceOf(address(c));

        // The deciding call: mint synth credited to `user` from the pool's free LP.
        // Only succeeds if msg.sender is a curated pool and LP tokens were moved to c.
        bool mintReverted;
        try c.mintSynth(user, synthAmount) returns (uint syntheticAmount) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        uint afterLPBalance = c.getmapAddress_LPBalance(pool);
        uint afterLPDebt = c.getmapAddress_LPDebt(pool);
        uint afterSupply = c.totalSupply();
        uint userBal = c.balanceOf(user);

        // General rule: if the mint succeeded, synthetic supply increased by exactly
        // the requested amount and all of it was credited to the given member;
        // otherwise nothing may have moved.  Also, the pool's recorded LP balance
        // may only grow when a mint succeeds, and the LP debt grows by exactly the
        // amount requested, independently of any other pool.
        if (!mintReverted) {
            assert(
                afterSupply == beforeSupply + synthAmount &&
                userBal >= synthAmount &&
                afterLPDebt == beforeLPDebt + synthAmount &&
                afterLPBalance >= beforeLPBalance
            );
        } else {
            assert(
                afterSupply == beforeSupply &&
                afterLPDebt == beforeLPDebt &&
                afterLPBalance == beforeLPBalance
            );
        }
    }

    receive() external payable {}
}

