contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint256 amount, uint256 lpBalanceBefore, uint256 lpDebtBefore) public payable {
        require(member != address(0));
        require(amount > 0);
        require(lpDebtBefore > 0);
        require(address(this).balance >= amount);

        // Set up the state so that C holds synthetic tokens and a pool record exists.
        // The test contract must act as the member/pool in the mappings when it calls c.burnSynth().
        // Since the test contract is the only caller, msg.sender inside c.burnSynth() is address(this).

        // Ensure the member variable is usable as a pool address for c.burnSynth, but the call is
        // always made by this contract, so the relevant map entries are for address(this).
        // We set up by calling mintSynth as the pool (msg.sender of c.mintSynth is this contract).
        // However, mintSynth has onlyPool modifier and requires the pool to be curated.
        // In a generic property test we cannot rely on curation; instead we set up directly?
        // The checker deploys c; we can only interact through public functions. We cannot set private mappings.
        // So burnSynth will revert if mapSynth_LPDebt[msg.sender] is zero or synthetic balance is zero.
        // Therefore the rule below should account for a revert scenario.

        // We can attempt to reach burnSynth. Since we cannot reliably set up, we express a rule
        // that holds even if burnSynth reverts. If it reverts, no state change is observed.
        // The general rule: if burnSynth succeeds, then LP debt decreases by the synthetic balance
        // held by C, and LP balance decreases by the computed amountUnits.
        // We read the public getters before and after. Both getters are public mappings.

        uint256 debtBefore = c.getmapAddress_LPDebt(address(this));
        uint256 lpBefore = c.getmapAddress_LPBalance(address(this));
        uint256 synthBalBefore = c.balanceOf(address(this));

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 debtAfter = c.getmapAddress_LPDebt(address(this));
        uint256 lpAfter = c.getmapAddress_LPBalance(address(this));

        // If burnSynth reverted, no state change should occur for the mappings.
        // If it succeeded, then debtAfter = debtBefore - synthBalBefore and
        // lpAfter = lpBefore - (synthBalBefore * lpBefore / debtBefore).
        // We encode this implication directly in the assert.
        // Need to guard against division by zero: synthBalBefore * lpBefore / debtBefore is computed only if debtBefore > 0 and synthBalBefore > 0.
        // Since getters are public, this is a general rule.
        assert(
            reverted
                ? (debtAfter == debtBefore && lpAfter == lpBefore)
                : (debtBefore >= synthBalBefore &&
                   debtAfter == debtBefore - synthBalBefore &&
                   (synthBalBefore == 0 || debtBefore == 0 ||
                    lpAfter == lpBefore - (synthBalBefore * lpBefore / debtBefore)))
        );
    }
    receive() external payable {}
}

