        if (spender == address(this) && !reverted) {
            uint256 senderAfter = c.balanceOf(sender);
            uint256 recipientAfter = c.balanceOf(recipient);
            uint256 allowanceAfter = c.allowance(sender, spender);
            assert(senderAfter == senderBefore - amountToTransfer &&
                   recipientAfter == recipientBefore + amountToTransfer &&
                   allowanceAfter == (allowanceBefore == type(uint256).max ? type(uint256).max : allowanceBefore - amountToTransfer));
        } else {
            assert(c.balanceOf(sender) == senderBefore &&
                   c.balanceOf(recipient) == recipientBefore);
        }
    }

    receive() external payable {}
}

