contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0), "zero address");
        require(address(this).balance >= 0, "balance");

        uint256 fromBalBefore = c.balanceOf(from);
        uint256 toBalBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 fromBalAfter = c.balanceOf(from);
            uint256 toBalAfter = c.balanceOf(to);
            uint256 allowanceAfter = c.allowance(from, address(this));

            if (from == to) {
                if (fromBalBefore >= amount) {
                    assert(fromBalAfter == fromBalBefore && toBalAfter == toBalBefore);
                }
            } else {
                assert(fromBalBefore >= amount);
                assert(fromBalAfter == fromBalBefore - amount);
                assert(toBalAfter == toBalBefore + amount);
            }

            if (allowanceBefore != type(uint256).max) {
                if (from != to) {
                    assert(allowanceBefore >= amount);
                    assert(allowanceAfter == allowanceBefore - amount);
                }
            } else {
                assert(allowanceAfter == type(uint256).max);
            }
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

