contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 approveAmount) public {
        // Precondition: amount > 0, caller (this contract) and sender/recipient are nonzero.
        require(amount > 0, "amount zero");
        require(sender != address(0), "sender zero");
        require(recipient != address(0), "recipient zero");
        require(address(this) != address(0), "caller zero");

        // Make sure the spender (this contract) has an allowance from sender.
        c.approve(address(this), approveAmount);

        // If sender has insufficient balance or allowance, the call must revert.
        // The rule below distinguishes the two cases.
        uint256 supplyBefore = c.totalSupply();
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 senderBefore = c.balanceOf(sender);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 recipientAfter = c.balanceOf(recipient);
        uint256 senderAfter = c.balanceOf(sender);

        // The general rule:
        // 1. If the call did not revert, totalSupply is conserved, exactly amount units
        //    moved from sender to recipient, and the allowance decreased by amount
        //    (unless it was an infinite allowance, which this contract does not set here).
        // 2. If the call reverted, totalSupply and balances are unchanged.
        assert(
            (reverted && supplyAfter == supplyBefore && recipientAfter == recipientBefore && senderAfter == senderBefore) ||
            (!reverted && supplyAfter == supplyBefore && recipientAfter == recipientBefore + amount && senderAfter == senderBefore - amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
