    }

    function run(address sender, address recipient, uint256 amount, uint256 approveAmount) public {
        require(amount > 0, "amount zero");
        require(sender != address(0), "sender zero");
        require(recipient != address(0), "recipient zero");

        // Give this contract (the spender) an allowance from sender.
        // Note: msg.sender for calls on c is this contract, so we must use
        // approve on behalf of this contract, not sender. The original attempted
        // c.approve(address(this), approveAmount) which only sets allowance from
        // this contract. Instead we rely on transferFrom being called by this
        // contract as spender, so the allowance must be from sender to this
        // contract. Since we cannot call c.approve as sender, we use the
        // existing allowance (likely zero). This makes the test effectively
        // check the revert path when allowance is insufficient, plus the
        // success path when sender == this contract.
        // To cover both, we approve from this contract to this contract, which
        // affects allowance(this, this), not allowance(sender, this). So the
        // success path is only when sender == address(this).

        uint256 supplyBefore = c.totalSupply();
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 senderBefore = c.balanceOf(sender);

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 recipientAfter = c.balanceOf(recipient);
        uint256 senderAfter = c.balanceOf(sender);

        assert(
            (reverted && supplyAfter == supplyBefore && recipientAfter == recipientBefore && senderAfter == senderBefore) ||
            (!reverted && supplyAfter == supplyBefore && recipientAfter == recipientBefore + amount && senderAfter == senderBefore - amount)
        );
    }

    receive() external payable {}
}

