    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");

        uint256 senderBefore = c.balanceOf(address(this));
        require(senderBefore >= amount, "insufficient balance");
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);

        if (!reverted && recipient != address(this)) {
            assert(senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount);
        } else {
            assert(senderAfter == senderBefore && recipientAfter == recipientBefore);
        }
    }

    receive() external payable {}
}

