contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public payable {
        require(from != to, "from == to");
        require(from != address(this), "from == this");
        require(to != address(this), "to == this");

        uint256 supplyBefore = c.totalSupply();
        uint256 fromBefore = c.balanceOf(from);
        uint256 toBefore = c.balanceOf(to);

        bool observedRevert;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            require(ok, "returned false");
            observedRevert = false;
        } catch {
            observedRevert = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 fromAfter = c.balanceOf(from);
        uint256 toAfter = c.balanceOf(to);

        assert(
            (supplyBefore == supplyAfter) &&
            (
                observedRevert ||
                ((fromBefore + toBefore) == (fromAfter + toAfter))
            )
        );
    }

    receive() external payable {}
}

