contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address pool, address member, uint amount) public {
        require(amount > 0, "amount must be positive");

        uint beforeBalance = c.balanceOf(member);
        uint beforePoolBalance = c.getmapAddress_LPBalance(pool);

        uint returned = c.mintSynth(member, amount);

        uint afterBalance = c.balanceOf(member);
        uint afterPoolBalance = c.getmapAddress_LPBalance(pool);

        assert(returned == amount);
        assert(afterBalance - beforeBalance == amount);
        assert(afterPoolBalance >= beforePoolBalance);
    }
}
